import Foundation

func scoreToCategory(score: Double) -> String {
    if score >= 0.5 {
        return "StrongPositive"
    } else if score <= -0.5 {
        return "StrongNegative"
    }
    return "Moderate"
}

let tag = scoreToCategory(score: 0.85)
print("Tag: \(tag)")

