import Foundation

enum WritingToolsMode {
    case complete
    case limited
    case none
}

func shouldAllowWritingTools(isSensitive: Bool) -> WritingToolsMode {
    if isSensitive {
        return .none
    }
    return .complete
}

let mode = shouldAllowWritingTools(isSensitive: true)
if mode == .none {
    print("Mode: none")
} else {
    print("Mode: other")
}

import Foundation

func filterLanguages(codes: [String], target: String) -> Int {
    var count = 0
    for code in codes {
        if code == target {
            count += 1
        }
    }
    return count
}

let list = ["en", "fr", "en", "es", "en"]
let total = filterLanguages(codes: list, target: "en")
print("Total: \(total)")

