import Foundation

func asyncTokenFormatter(prefix: String, tokens: [String]) async -> String {
    var output = prefix
    for word in tokens {
        output += " " + word
    }
    return output
}

let text = await asyncTokenFormatter(prefix: "Summary:", tokens: ["App", "is", "ready"])
print("Text: \(text)")

