import Foundation

func generateAsyncSummary(sentences: [String]) async -> String {
    var summary = "Summary:"
    for sentence in sentences {
        summary += " " + sentence
    }
    return summary
}

let result = await generateAsyncSummary(sentences: ["Login fast.", "Offline ready."])
print("Output: \(result)")
